// Define a class to represent the error
class VectorIndexError {
public:
    VectorIndexError(int v) : m_badValue(v) { }
    ~VectorIndexError() { }
    void diagnostic() {
        cerr &lt;&lt; "index " &lt;&lt; m_ badValue
        &lt;&lt; "out of range!"; }
private:
    int m_badValue;
};


int func() {
    Vector&lt;int&gt; v(12);
