virtual<pre><code>class XYPos{...};
class Shape{
    public:
        Shape();
        virtual ~Shape();
        virtual void render();
        void move(const XYPos&amp;);
        virtual void resize();
    protected:
        XYPos center;
};

class Ellipse : public Shape{
    public:
        Ellipse(float maj, float minr);
        virtual void render(); // will define own 
    protected:
        float major_axis, minor_axis;
};

class Circle : public Ellipse{
    public:
        Circle(float radius) : Ellipse(radius, radius){}
        virtual void rendor();
};

void render(Shape* p) {
    p-&gt;render(); // calls correct render function
} // for given Shape!

void func() {
    Ellipse ell(10, 20);
    ell.render(); // static -- Ellipse::render();

    Circle circ(40);
    circ.render(); // static -- Circle::render();

    render(&amp;ell); // dynamic -- Ellipse::render();
    render(&amp;circ); // dynamic -- Circle::render()
}
</code></pre>

